import{guardianFigure,guardianKeyframes}from'./expedition-guardian-motion.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function guardianDetailFrames(plan){
 if(!plan)return[];const k=guardianKeyframes(plan),parts=Object.entries(k.parts);
 if(!plan.beats.length)return[{label:'当前结算姿态',eventId:null,transforms:Object.fromEntries(parts.map(([key,p])=>[key,p.settled]))}];
 return[{label:'动作起点',eventId:null},...plan.beats.map(b=>({label:b.label,eventId:b.eventId})),{label:'当前结算姿态',eventId:null}].map((f,i)=>({...f,transforms:Object.fromEntries(parts.map(([key,p])=>[key,p.frames[i].transform]))}));
}
export function guardianDetailView(plan,{open=false,reduced=false}={}){
 if(!plan)return'';const frames=guardianDetailFrames(plan);return `<details class="guardian-motion-detail" ${open?'open':''}><summary>放大查看守卫动作</summary><div class="guardian-detail-layout"><div class="guardian-detail-art">${guardianFigure(plan)}</div><div><p>按本步已记录顺序重看动作；HP、MP与阵位保持上方当前快照，动作时长不代表实际战斗秒数。挡架检定不保证免伤。</p><div class="guardian-detail-frames" aria-label="选择静态动作姿态">${frames.map((f,i)=>`<button type="button" data-guardian-detail-frame="${i}" aria-pressed="${i===frames.length-1}">${esc(f.label)}${f.eventId===null?'':`<small>记录 ${esc(f.eventId)}</small>`}</button>`).join('')}</div><div class="bar"><button type="button" data-guardian-detail-play ${reduced||!plan.beats.length?'disabled':''}>重播本步动作</button><button type="button" data-guardian-detail-stop>显示结算姿态</button></div><p data-guardian-detail-status role="status"></p></div></div></details>`;
}
export function mountGuardianDetail(root,plan,{speed=()=>1,reduced=false,beforeInspect=()=>{}}={}){
 if(!root||!plan)return null;const frames=guardianDetailFrames(plan),svg=root.querySelector('.guardian-figure'),status=root.querySelector('[data-guardian-detail-status]'),play=root.querySelector('[data-guardian-detail-play]');let running=[],generation=0,disposed=false;
 function show(i){const f=frames[i];if(!f)return;for(const[key,transform]of Object.entries(f.transforms))svg.querySelector('[data-rig-part="'+key+'"]').style.transform=transform;for(const b of root.querySelectorAll('[data-guardian-detail-frame]'))b.setAttribute('aria-pressed',String(Number(b.dataset.guardianDetailFrame)===i));root.dataset.guardianDetailSelectedFrame=String(i);root.dataset.guardianDetailEvent=f.eventId===null?'':String(f.eventId);root.querySelector('.guardian-pose-label').textContent=f.label;status.textContent=f.label+(f.eventId===null?'':' · 原记录 '+f.eventId)+(reduced?' · 已减少动态效果，可逐个查看静态姿态。':' · 数值仍为当前回放快照。');}
 function cancel(){generation++;for(const a of running)a.cancel();running=[];root.dataset.guardianDetailPlaying='false';show(frames.length-1);}
 function setReduced(value){reduced=Boolean(value);if(reduced)cancel();play.disabled=reduced||!plan.beats.length;if(reduced&&root.ownerDocument.activeElement===play)root.querySelector('[data-guardian-detail-frame="'+(frames.length-1)+'"]').focus({preventScroll:true});if(!root.dataset.guardianDetailPlaying||root.dataset.guardianDetailPlaying==='false')show(Number(root.dataset.guardianDetailSelectedFrame??frames.length-1));}
 function click(e){const pose=e.target.closest('button[data-guardian-detail-frame]');if(pose){const i=Number(pose.dataset.guardianDetailFrame);if(!Number.isInteger(i)||!frames[i])return;beforeInspect();cancel();show(i);return;}if(e.target.closest('[data-guardian-detail-stop]')){beforeInspect();cancel();return;}if(!e.target.closest('[data-guardian-detail-play]')||reduced||!plan.beats.length)return;beforeInspect();cancel();const k=guardianKeyframes(plan,{speed:speed(),reduced});if(!k.animated)return;const seq=++generation;root.dataset.guardianDetailPlaying='true';status.textContent='正在按原记录顺序重播：'+plan.beats.map(b=>b.label).join(' → ')+'。数值仍为当前回放快照。';for(const b of root.querySelectorAll('[data-guardian-detail-frame]'))b.setAttribute('aria-pressed','false');for(const[key,part]of Object.entries(k.parts)){const n=svg.querySelector('[data-rig-part="'+key+'"]');n.style.transform=part.settled;if(typeof n.animate==='function')running.push(n.animate(part.frames,{duration:k.duration,easing:'linear',fill:'none'}));}svg.dataset.motionDuration=String(k.duration);Promise.all(running.map(a=>a.finished.catch(()=>null))).then(()=>{if(disposed||seq!==generation||!root.isConnected)return;running=[];root.dataset.guardianDetailPlaying='false';show(frames.length-1);});}
 const toggle=()=>{if(!root.open)cancel();};root.addEventListener('click',click);root.addEventListener('toggle',toggle);cancel();setReduced(reduced);return{cancel,setReduced,destroy(){disposed=true;cancel();root.removeEventListener('click',click);root.removeEventListener('toggle',toggle);}};
}
